 static int count;static string root,token;static JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};
 class Result{public int Code;public string Body;public WebHeaderCollection Headers;}
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
 static Result Call(string path,string method="GET",string body=null,string origin=null,string host=null,bool auth=true,string scanId=null){var req=(HttpWebRequest)WebRequest.Create(root+path);req.Method=method;req.Proxy=null;req.Timeout=15000;if(auth)req.Headers["X-LocalLens-Token"]=token;if(scanId!=null)req.Headers["X-LocalLens-Scan-Id"]=scanId;if(origin!=null)req.Headers["Origin"]=origin;if(host!=null)req.Host=host;if(body!=null){byte[] bytes=Encoding.UTF8.GetBytes(body);req.ContentType="application/json";req.ContentLength=bytes.Length;using(var s=req.GetRequestStream())s.Write(bytes,0,bytes.Length);}HttpWebResponse response;try{response=(HttpWebResponse)req.GetResponse();}catch(WebException e){response=(HttpWebResponse)e.Response;if(response==null)throw;}using(response)using(var reader=new StreamReader(response.GetResponseStream()))return new Result{Code=(int)response.StatusCode,Body=reader.ReadToEnd(),Headers=response.Headers};}
 static Dictionary<string,object> State(){return json.Deserialize<Dictionary<string,object>>(Call("/api/state").Body);}
 static string Raw(string headers){using(var c=new TcpClient("127.0.0.1",53175)){c.ReceiveTimeout=5000;using(var s=c.GetStream()){byte[] bytes=Encoding.ASCII.GetBytes(headers);s.Write(bytes,0,bytes.Length);return new StreamReader(s).ReadToEnd();}}}
 static int Main(){try{using(var automatic=new LocalWebHost(0)){Check(new Uri(automatic.Url).Port>0,"system-assigned loopback port is supported");}var blocker=new TcpListener(IPAddress.Loopback,0);blocker.Start();try{int blockedPort=((IPEndPoint)blocker.LocalEndpoint).Port;using(var fallback=LocalWebHost.Start(blockedPort,true)){Check(new Uri(fallback.Url).Port!=blockedPort,"unavailable preferred port falls back automatically");}bool strictFailed=false;try{using(var strict=LocalWebHost.Start(blockedPort,false)){}}catch(SocketException){strictFailed=true;}Check(strictFailed,"explicit unavailable port remains strict");}finally{blocker.Stop();}using(var server=new LocalWebHost(53175)){root=server.Url.TrimEnd('/');var index=Call("/",auth:false);Check(index.Code==200&&index.Body.Contains("你是「")&&index.Body.Contains("gauge-arc")&&index.Body.Contains("signal-list")&&index.Body.Contains("score-number")&&!index.Body.Contains("是线索"),"embedded web UI serves without filesystem paths");token=Regex.Match(index.Body,"name=\"locallens-token\" content=\"([^\"]+)\"").Groups[1].Value;Check(token.Length>=40,"per-process session token is generated");Check(index.Headers["Content-Security-Policy"].Contains("frame-ancestors 'none'")&&index.Headers["X-Content-Type-Options"]=="nosniff","browser isolation headers");Check(Call("/app.js",auth:false).Code==200&&Call("/styles.css",auth:false).Code==200,"bundled assets served");Check(Call("/risk-core.js",auth:false).Code==200,"browser risk model is embedded and served locally");foreach(string mascot in new[]{"doze","scan","result","medium","high"}){var asset=Call("/mascot-"+mascot+".png",auth:false);Check(asset.Code==200&&asset.Headers["Content-Type"].StartsWith("image/png")&&asset.Body.Length>1000,"generated mascot asset is embedded and served: "+mascot);}Check(Call("/src/catalog.json",auth:false).Code==404&&Call("/../README.md",auth:false).Code==404,"arbitrary files are not exposed");Check(Call("/api/state",auth:false).Code==403,"API rejects absent token");Check(Call("/api/state",origin:"https://example.com").Code==403,"API rejects foreign origin");Check(Call("/api/state",host:"example.com:53175").Code==403,"API rejects DNS rebinding host");Check(Call("/api/scan").Code==404,"GET cannot start a scan");Check(Call("/api/scan","POST","null").Code==400,"missing scan options rejected");var state=State();Check(!(bool)state["running"]&&new[]{"AutoDiscoverFiles","History","Online","Wifi","BrowserContent","Probes","RequestLocation","DeviceIdentifiers","Ocr"}.All(k=>(bool)((Dictionary<string,object>)state["options"])[k])&&(int)((Dictionary<string,object>)state["options"])["MonitorSeconds"]==30,"server starts idle with all supported scan options enabled");Check(Call("/api/baseline").Code==400&&Call("/api/export").Code==400,"export and baseline gated before scan");Check(Raw("POST /api/import HTTP/1.1\r\nHost: 127.0.0.1:53175\r\nContent-Length: 1048577\r\n\r\n").StartsWith("HTTP/1.1 400"),"oversized request rejected before reading body");Check(Raw("POST /api/import HTTP/1.1\r\nHost: 127.0.0.1:53175\r\nTransfer-Encoding: chunked\r\n\r\n").StartsWith("HTTP/1.1 400"),"unsupported transfer encoding rejected");Check(Call("/api/import?kind=browser","POST","not json").Code==400,"malformed import rejected");Check(Call("/network-core.js",auth:false).Code==200&&Call("/network.js",auth:false).Code==200,"browser network assets embedded");Check(Call("/api/browser-network").Code==404,"GET cannot submit network observations");Check(Call("/api/browser-network","POST","null").Code==400,"invalid network observation rejected");
Check(Call("/api/network-countries").Code==404,"GET cannot trigger outbound country queries");
Check(Call("/api/network-countries","POST","[]",auth:false).Code==403,"country lookup requires local session token");
Check(Call("/api/network-countries","POST","[\"192.168.1.1\"]").Code==400,"country lookup rejects private addresses without querying a third party");
Check(Call("/api/network-countries","POST","[\"8.8.8.8\",\"127.0.0.1\"]").Code==400,"mixed public/private batch rejected before network access");
Check(Call("/api/network-countries","POST",json.Serialize(Enumerable.Repeat("8.8.8.8",17).ToArray())).Code==400,"country lookup batch bound enforced before network access");
var network=new BrowserNetworkReport{RuleVersion="ChinaUserEvidence2.4",StartedUtc="2026-10-16T00:00:00Z",FinishedUtc="2026-10-16T00:00:10Z",Browser="Test browser",Findings=new[]{1,3,6}.Select(id=>new Finding{Id=id,State=id==6?"发现线索":"未发现",Summary="Synthetic sample",MatchingEvidence=id==6?"country=CN":"",Evidence="PRIVATE_NETWORK_EVIDENCE",Limit="Synthetic sample only"}).ToList()};Check(Call("/api/browser-network","POST",json.Serialize(network),auth:false).Code==403,"network observation requires token");Check(Call("/api/browser-network","POST",json.Serialize(network)).Code==200&&State()["browserNetwork"]!=null,"browser observation retained in local service");Check(Call("/api/browser-network","POST","{}").Code==400&&State()["browserNetwork"]!=null,"invalid update does not erase previous browser results");Check(Call("/api/import?kind=unknown","POST","{}").Code==400,"import kind allowlist");var imported=Call("/api/import?kind=browser","POST","{\"app\":\"LocalLens BrowserCheck 2.0\",\"time\":\"2026-10-16T00:00:00Z\",\"environment\":{\"language\":\"en-US\"}}");Check(imported.Code==200&&File.Exists(json.Deserialize<Dictionary<string,string>>(imported.Body)["path"]),"valid JSON import stored locally");Check(Call("/api/scan","POST","{\"History\":false,\"Online\":false}").Code==200,"scan starts through authenticated API");state=State();string batch=(string)state["scanId"];Check(!String.IsNullOrWhiteSpace(batch)&&state["browserNetwork"]==null,"new main scan creates a batch and clears prior browser results");Check(Call("/api/browser-network","POST",json.Serialize(network)).Code==409&&Call("/api/browser-network","POST",json.Serialize(network),scanId:"expired").Code==409,"network results require the current main scan batch");Check(Call("/api/browser-network","POST",json.Serialize(network),scanId:batch).Code==200,"same batch browser results accepted during the main scan");Check(Call("/api/scan","POST","{}").Code==409,"concurrent scan rejected");Check(Call("/api/cancel","POST","{}").Code==200,"cancel request accepted");DateTime until=DateTime.UtcNow.AddSeconds(20);do{Thread.Sleep(50);state=State();}while((bool)state["running"]&&DateTime.UtcNow<until);Check(!(bool)state["running"]&&!(bool)state["completed"]&&(bool)state["hasReport"]&&(bool)state["cancelled"],"cancel finishes with persistent partial report status");Check(Call("/api/baseline").Code==400,"partial scan cannot produce baseline");Check(Call("/api/browser-network","POST",json.Serialize(network),scanId:batch).Code==409,"late network result cannot overwrite cancelled scan");Check(Call("/api/export?format=json",scanId:"expired").Code==409,"export rejects a different main scan batch");Check((string)json.Deserialize<Dictionary<string,object>>(Call("/api/export?format=json",scanId:batch).Body)["ScanId"]==batch,"export includes matching main scan batch");var exported=Call("/api/export?format=json");var report=json.Deserialize<AuditReport>(exported.Body);Check(exported.Code==200&&report.Snapshot==null&&report.Findings.Count==69&&report.Findings.All(f=>f.Sources==null&&f.Evidence.StartsWith("[摘要")),"JSON download strips raw and nested evidence");Check(report.BrowserNetwork!=null&&report.BrowserNetwork.Findings.All(f=>!f.Evidence.Contains("PRIVATE_NETWORK_EVIDENCE"))&&report.BrowserNetwork.Findings.Any(f=>f.State=="发现线索"),"summary includes network state without raw evidence");Check(report.BrowserNetwork.Findings.First(f=>f.Id==6).MatchingEvidence.Contains("country=CN"),"network summary retains only safe CN proof for integrated rescoring");var html=Call("/api/export?format=html");Check(html.Code==200&&html.Headers["Content-Disposition"].Contains(".html")&&html.Body.Contains("扫描中断"),"HTML attachment preserves interrupted status");var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(LocalWebHost).GetField("options",flags).SetValue(server,new ScanOptions{Online=true,Probes=true});typeof(LocalWebHost).GetField("scanCancelled",flags).SetValue(server,false);typeof(LocalWebHost).GetField("browserNetworkDone",flags).SetValue(server,false);typeof(LocalWebHost).GetField("browserNetwork",flags).SetValue(server,null);typeof(LocalWebHost).GetField("started",flags).SetValue(server,(DateTime?)DateTime.UtcNow);Check((bool)State()["browserNetworkRunning"]&&Call("/api/export?format=json",scanId:batch).Code==400,"export waits for the browser portion of the unified batch");Check(Call("/api/browser-network/skip","POST","{}",scanId:"expired").Code==409,"skip cannot end another scan batch");Check(Call("/api/browser-network/skip","POST","{}",scanId:batch).Code==200&&!(bool)State()["browserNetworkRunning"],"same batch can end unreadable browser sampling as skipped");Check(State()["browserNetwork"]!=null&&json.Deserialize<BrowserNetworkReport>(json.Serialize(State()["browserNetwork"])).Findings.All(f=>f.State=="读取失败"),"skipped browser sampling retains three source diagnoses rather than disappearing");Check(Call("/api/browser-network","POST",json.Serialize(network),scanId:batch).Code==409,"late result cannot replace explicitly skipped browser sampling");typeof(LocalWebHost).GetField("browserNetworkDone",flags).SetValue(server,false);typeof(LocalWebHost).GetField("browserNetwork",flags).SetValue(server,null);typeof(LocalWebHost).GetField("started",flags).SetValue(server,(DateTime?)DateTime.UtcNow.AddSeconds(-91));Check(Call("/api/browser-network","POST",json.Serialize(network),scanId:batch).Code==409&&(bool)State()["browserNetworkDone"],"deadline rejects late browser result without waiting for a state poll");Check(Call("/api/shutdown","POST","{}").Code==200&&server.ShutdownRequested,"authenticated shutdown signal");Console.WriteLine("WEB CHECKS PASSED: "+count);return 0;}}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
